package id.payu.backoffice.adapter.persistence; import id.payu.backoffice.adapter.persistence.entity.KycReviewEntity; import id.payu.backoffice.domain.KycReview; import org.springframework.stereotype.Component;
@Component public class KycReviewMapper {public KycReview toDomain(KycReviewEntity e){return KycReview.reconstitute(e.getId(),e.getUserId(),e.getAccountNumber(),e.getDocumentType(),e.getDocumentNumber(),e.getDocumentUrl(),e.getFullName(),e.getAddress(),e.getPhoneNumber(),e.getStatus(),e.getNotes(),e.getReviewedBy(),e.getReviewedAt(),e.getCreatedAt(),e.getVersion());} public KycReviewEntity toEntity(KycReview d){return KycReviewEntity.builder().id(d.getId()).userId(d.getUserId()).accountNumber(d.getAccountNumber()).documentType(d.getDocumentType()).documentNumber(d.getDocumentNumber()).documentUrl(d.getDocumentUrl()).fullName(d.getFullName()).address(d.getAddress()).phoneNumber(d.getPhoneNumber()).status(d.getStatus()).notes(d.getNotes()).reviewedBy(d.getReviewedBy()).reviewedAt(d.getReviewedAt()).createdAt(d.getCreatedAt()).version(d.getVersion()).build();}}
